A higher-order function is a function that takes one or more functions as arguments or returns a function as its result. This enables powerful patterns like function composition and callbacks.

```python
def apply_twice(f, x):
    return f(f(x))

result = apply_twice(lambda x: x * 2, 5)  # Returns 20
```

A decorator is a function that wraps another function or class, modifying or enhancing its behavior without changing its source code. Decorators use the @ syntax for application.

```python
def my_decorator(func):
    def wrapper():
        print("Something before")
        func()
        print("Something after")
    return wrapper

@my_decorator
def say_hello():
    print("Hello!")

say_hello()
```

A decorator that accepts arguments requires an extra layer of nesting: the outermost function takes decorator arguments, the middle function is the actual decorator, and the innermost function is the wrapper.

```python
def repeat(times):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for _ in range(times):
                func(*args, **kwargs)
        return wrapper
    return decorator

@repeat(times=3)
def greet(name):
    print(f"Hello {name}")

greet("Alice")
```

functools.wraps copies metadata from the original function to the wrapper function, preserving __name__, __doc__, and __module__. This prevents loss of function identity and documentation.

```python
from functools import wraps

def my_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@my_decorator
def add(a, b):
    """Add two numbers."""
    return a + b

print(add.__name__)  # 'add' (not 'wrapper')
print(add.__doc__)   # 'Add two numbers.'
```

Multiple decorators are applied bottom-to-top. The bottom decorator is applied first, then its result is decorated by the next one up.

```python
from functools import wraps

def decorator1(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print("D1 before")
        result = func(*args, **kwargs)
        print("D1 after")
        return result
    return wrapper

def decorator2(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print("D2 before")
        result = func(*args, **kwargs)
        print("D2 after")
        return result
    return wrapper

@decorator1
@decorator2
def hello():
    print("Hello")

hello()
# Output: D1 before, D2 before, Hello, D2 after, D1 after
```

A class decorator is a function that takes a class as input and returns a modified class or a wrapper. It can add methods, modify attributes, or control class instantiation.

```python
def add_repr(cls):
    def __repr__(self):
        attrs = ', '.join(f"{k}={v}" for k, v in self.__dict__.items())
        return f"{cls.__name__}({attrs})"
    cls.__repr__ = __repr__
    return cls

@add_repr
class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

p = Person("Alice", 30)
print(p)  # Person(name=Alice, age=30)
```

functools.lru_cache decorates a function to cache its results. It stores the most recent N unique calls, using an LRU eviction policy. Perfect for expensive computations.

```python
from functools import lru_cache

@lru_cache(maxsize=128)
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

print(fibonacci(30))  # Much faster than without caching
print(fibonacci.cache_info())  # CacheInfo(hits=28, misses=31, ...)
```

functools.cache (Python 3.9+) is simpler and unbounded, caching all results indefinitely. functools.lru_cache has a bounded size with LRU eviction and is suitable when memory is limited.

```python
from functools import cache, lru_cache

@cache  # Unbounded, equivalent to lru_cache(maxsize=None)
def expensive_func(x):
    return x ** 2

@lru_cache(maxsize=32)  # Bounded, evicts least-recently-used
def bounded_func(x):
    return x ** 2
```

Dict comprehension creates dictionaries using a concise syntax similar to list comprehension. It uses key:value pairs.

```python
# Create a mapping of numbers to their squares
squares = {x: x ** 2 for x in range(5)}
print(squares)  # {0: 0, 1: 1, 2: 4, 3: 9, 4: 16}

# Create a dict from key-value pairs
pairs = [("a", 1), ("b", 2), ("c", 3)]
dict_from_pairs = {k: v for k, v in pairs}
print(dict_from_pairs)  # {'a': 1, 'b': 2, 'c': 3}
```

Set comprehension creates sets using syntax similar to list comprehension. It automatically removes duplicates and is unordered.

```python
# Create a set of unique squares
squares = {x ** 2 for x in range(10)}
print(squares)  # {0, 1, 4, 9, 16, 25, 36, 49, 64, 81}

# Create a set of even numbers
even = {x for x in range(10) if x % 2 == 0}
print(even)  # {0, 2, 4, 6, 8}
```

Memoization is caching function results to avoid recomputation. Common patterns include using lru_cache, cache, or implementing manual caching with dictionaries.

```python
from functools import lru_cache

# Manual memoization
def fib_manual(n, memo={}):
    if n in memo:
        return memo[n]
    if n < 2:
        return n
    memo[n] = fib_manual(n-1, memo) + fib_manual(n-2, memo)
    return memo[n]

# Using decorator
@lru_cache(maxsize=None)
def fib_cached(n):
    if n < 2:
        return n
    return fib_cached(n-1) + fib_cached(n-2)
```

A metaclass is a class of a class. It defines how a class behaves, including how it's created and how its instances behave. All classes are instances of their metaclass (usually `type`).

```python
class Meta(type):
    def __new__(mcs, name, bases, dct):
        print(f"Creating class {name}")
        return super().__new__(mcs, name, bases, dct)

class MyClass(metaclass=Meta):
    pass

# Output: Creating class MyClass
```

__new__() in a metaclass is called before __init__() to create the class object. It receives the class name, base classes, and class attributes dictionary, and must return the new class.

```python
class Meta(type):
    def __new__(mcs, name, bases, dct):
        print(f"__new__: Creating {name}")
        # Add a class attribute
        dct['created_by_meta'] = True
        return super().__new__(mcs, name, bases, dct)

    def __init__(cls, name, bases, dct):
        print(f"__init__: Initializing {name}")
        super().__init__(name, bases, dct)

class MyClass(metaclass=Meta):
    pass

print(MyClass.created_by_meta)  # True
```

__init_subclass__() is called when a subclass is created. It's a simpler alternative to metaclasses for customizing subclass creation without defining a metaclass.

```python
class Base:
    def __init_subclass__(cls, color=None, **kwargs):
        super().__init_subclass__(**kwargs)
        cls.color = color

class RedClass(Base, color="red"):
    pass

class BlueClass(Base, color="blue"):
    pass

print(RedClass.color)   # red
print(BlueClass.color)  # blue
```

__getattribute__() is called for every attribute access, while __getattr__() is only called when the attribute is not found. __getattribute__() is more powerful but requires care to avoid infinite recursion.

```python
class MyClass:
    def __init__(self):
        self.x = 10

    def __getattribute__(self, name):
        print(f"__getattribute__ called for {name}")
        return super().__getattribute__(name)

    def __getattr__(self, name):
        print(f"__getattr__ called for {name}")
        return "not found"

obj = MyClass()
print(obj.x)  # __getattribute__ called for x
print(obj.y)  # __getattribute__ called for y, then __getattr__ called for y
```

A descriptor is an object with __get__(), __set__(), or __delete__() methods that controls how attributes are accessed. Descriptors enable properties, methods, and computed attributes.

```python
class Descriptor:
    def __get__(self, obj, objtype=None):
        return "Descriptor value"

    def __set__(self, obj, value):
        print(f"Setting value to {value}")

    def __delete__(self, obj):
        print("Deleting value")

class MyClass:
    attr = Descriptor()

obj = MyClass()
print(obj.attr)     # Descriptor value
obj.attr = 42       # Setting value to 42
del obj.attr        # Deleting value
```

functools.wraps() is a decorator that copies metadata from the decorated function to the wrapper, preserving __name__, __doc__, __module__, __qualname__, and __annotations__.

```python
from functools import wraps

def original_function():
    """Original docstring."""
    pass

def decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

decorated = decorator(original_function)
print(decorated.__name__)  # original_function (not wrapper)
print(decorated.__doc__)   # Original docstring.
```

Use functools.wraps and check if the first argument is callable to determine if it's being used with or without parentheses.

```python
from functools import wraps

def decorator_optional_args(arg=None):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            print(f"Decorator arg: {arg}")
            return func(*args, **kwargs)
        return wrapper

    # Called without arguments: @decorator
    if callable(arg):
        func = arg
        arg = None
        return decorator(func)
    # Called with arguments: @decorator(arg)
    return decorator

@decorator_optional_args
def func1():
    pass

@decorator_optional_args(arg="test")
def func2():
    pass
```

A property is a descriptor that allows methods to be accessed like attributes. It's created with the @property decorator and supports getters, setters, and deleters.

```python
class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if value <= 0:
            raise ValueError("Radius must be positive")
        self._radius = value

    @property
    def area(self):
        return 3.14159 * self._radius ** 2

c = Circle(5)
print(c.area)      # 78.53975
c.radius = 10      # Uses setter
print(c.area)      # 314.159
```

classmethod receives the class as the first argument (cls), while staticmethod receives no implicit first argument. Use classmethod for class-level data/operations, staticmethod for utility functions.

```python
class MyClass:
    class_var = 10

    @classmethod
    def class_method(cls):
        return f"Class variable: {cls.class_var}"

    @staticmethod
    def static_method(x):
        return x * 2

print(MyClass.class_method())   # Class variable: 10
print(MyClass.static_method(5)) # 10
```

yield pauses a function and returns a value, resuming from that point on the next call. It transforms a function into a generator.

```python
def countdown(n):
    while n > 0:
        yield n
        n -= 1

for num in countdown(3):
    print(num)  # 3, 2, 1
```

Function composition combines multiple functions into a single function where the output of one becomes the input of the next. It's useful for building pipelines.

```python
def compose(*functions):
    def composed(arg):
        result = arg
        for func in reversed(functions):
            result = func(result)
        return result
    return composed

def add_one(x):
    return x + 1

def double(x):
    return x * 2

def square(x):
    return x ** 2

f = compose(square, double, add_one)
print(f(3))  # ((3 + 1) * 2) ^ 2 = 64
```

Pipelining applies functions left-to-right, while composition applies them right-to-left. Both build chains of operations but with opposite ordering.

```python
def pipeline(*functions):
    def piped(arg):
        result = arg
        for func in functions:
            result = func(result)
        return result
    return piped

def add_one(x):
    return x + 1

def double(x):
    return x * 2

f = pipeline(add_one, double)  # add_one first, then double
print(f(3))  # (3 + 1) * 2 = 8
```

Tail recursion is when a recursive call is the last operation. Python doesn't optimize tail recursion (no tail call optimization), so deep recursion still hits the recursion limit.

```python
# Tail recursive (but not optimized by Python)
def factorial(n, acc=1):
    if n <= 1:
        return acc
    return factorial(n - 1, n * acc)

# Python doesn't optimize this, so it still uses stack depth
print(factorial(5))  # 120

# For deep recursion, use iteration instead
def factorial_iter(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result
```

Keyword-only arguments (after *) ensure parameters are passed by name, improving readability and preventing accidental positional argument issues.

```python
from functools import wraps

def decorator_with_kwargs(*, repeat=1, prefix=""):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(repeat):
                print(prefix)
                func(*args, **kwargs)
        return wrapper
    return decorator

@decorator_with_kwargs(repeat=2, prefix=">>")
def greet(name):
    print(f"Hello {name}")

greet("Alice")
# >> Hello Alice
# >> Hello Alice
```

Wrap the function call in try-except within the wrapper to handle and potentially transform exceptions.

```python
from functools import wraps

def handle_errors(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except ValueError as e:
            print(f"ValueError caught: {e}")
            return None
        except Exception as e:
            print(f"Unexpected error: {e}")
            raise
    return wrapper

@handle_errors
def convert_to_int(value):
    return int(value)

print(convert_to_int("42"))      # 42
print(convert_to_int("invalid")) # ValueError caught: invalid literal for int()...
```

functools.wraps() preserves most metadata, but for detailed inspection, you might need to manually copy __wrapped__ or use inspect utilities. Python 3.10+ has better annotation handling.

```python
from functools import wraps
from inspect import signature

def preserve_signature(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    # Manually set __wrapped__ for introspection
    wrapper.__wrapped__ = func
    return wrapper

@preserve_signature
def add(a: int, b: int) -> int:
    return a + b

print(add.__wrapped__)  # <function add at ...>
print(signature(add.__wrapped__))  # (a: int, b: int) -> int
```

A retry decorator attempts a function multiple times before giving up, useful for handling transient failures.

```python
from functools import wraps
import time

def retry(max_attempts=3, delay=1):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_attempts:
                        raise
                    print(f"Attempt {attempt} failed: {e}. Retrying...")
                    time.sleep(delay)
        return wrapper
    return decorator

@retry(max_attempts=3, delay=0.5)
def unreliable_function():
    import random
    if random.random() < 0.7:
        raise ValueError("Random failure")
    return "Success"
```

A TTL cache invalidates entries after a specified time, combining caching with expiration logic.

```python
from functools import wraps
import time

def cache_with_ttl(seconds=60):
    def decorator(func):
        cache = {}
        @wraps(func)
        def wrapper(*args):
            now = time.time()
            if args in cache:
                result, timestamp = cache[args]
                if now - timestamp < seconds:
                    return result
            result = func(*args)
            cache[args] = (result, now)
            return result
        return wrapper
    return decorator

@cache_with_ttl(seconds=2)
def expensive_operation(x):
    return x ** 2

print(expensive_operation(5))  # Computed
print(expensive_operation(5))  # Cached
time.sleep(2.1)
print(expensive_operation(5))  # Recomputed (cache expired)
```

A validation decorator checks arguments and/or return values before/after function execution, raising errors for invalid inputs.

```python
from functools import wraps

def validate_args(**validators):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for arg_name, validator in validators.items():
                if arg_name in kwargs:
                    value = kwargs[arg_name]
                    if not validator(value):
                        raise ValueError(f"Invalid {arg_name}: {value}")
            return func(*args, **kwargs)
        return wrapper
    return decorator

@validate_args(
    age=lambda x: isinstance(x, int) and 0 <= x <= 150,
    name=lambda x: isinstance(x, str) and len(x) > 0
)
def create_person(name, age):
    return f"{name}, {age} years old"

print(create_person("Alice", 30))  # OK
print(create_person("Bob", 200))   # ValueError: Invalid age: 200
```

A type-checking decorator validates that arguments and return values match expected types.

```python
from functools import wraps
from typing import get_type_hints

def type_check(func):
    hints = get_type_hints(func)
    @wraps(func)
    def wrapper(*args, **kwargs):
        # Simple type checking (not comprehensive)
        for arg_name, arg_type in hints.items():
            if arg_name != 'return':
                value = kwargs.get(arg_name)
                if value and not isinstance(value, arg_type):
                    raise TypeError(f"{arg_name} should be {arg_type}, got {type(value)}")
        result = func(*args, **kwargs)
        if 'return' in hints and not isinstance(result, hints['return']):
            raise TypeError(f"Return type should be {hints['return']}, got {type(result)}")
        return result
    return wrapper

@type_check
def add(a: int, b: int) -> int:
    return a + b

print(add(1, 2))      # 3
print(add(1, "2"))    # TypeError
```

A logging decorator records function calls, arguments, and results for debugging and monitoring.

```python
from functools import wraps
import logging

logging.basicConfig(level=logging.INFO)

def log_calls(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        logging.info(f"Calling {func.__name__} with args={args}, kwargs={kwargs}")
        try:
            result = func(*args, **kwargs)
            logging.info(f"{func.__name__} returned {result}")
            return result
        except Exception as e:
            logging.error(f"{func.__name__} raised {type(e).__name__}: {e}")
            raise
    return wrapper

@log_calls
def divide(a, b):
    return a / b

divide(10, 2)
divide(10, 0)
```

Method decorators must handle self parameter. They work like function decorators but need to preserve the method signature.

```python
from functools import wraps

def method_decorator(func):
    @wraps(func)
    def wrapper(self, *args, **kwargs):
        print(f"Calling {func.__name__} on {self.__class__.__name__}")
        return func(self, *args, **kwargs)
    return wrapper

class MyClass:
    @method_decorator
    def my_method(self, x):
        return x * 2

obj = MyClass()
print(obj.my_method(5))  # Calling my_method on MyClass
                         # 10
```

singledispatch enables function overloading based on the type of the first argument. Different implementations are registered for different types.

```python
from functools import singledispatch

@singledispatch
def process(arg):
    raise NotImplementedError(f"Cannot process {type(arg)}")

@process.register(int)
def _(arg):
    return arg * 2

@process.register(str)
def _(arg):
    return arg.upper()

@process.register(list)
def _(arg):
    return sum(arg)

print(process(5))       # 10
print(process("hello")) # HELLO
print(process([1, 2, 3]))  # 6
```

singledispatchmethod is like singledispatch but for methods. It dispatches based on the type of the first argument after self.

```python
from functools import singledispatchmethod

class Processor:
    @singledispatchmethod
    def process(self, arg):
        raise NotImplementedError

    @process.register(int)
    def _(self, arg):
        return arg * 2

    @process.register(str)
    def _(self, arg):
        return arg.upper()

proc = Processor()
print(proc.process(5))       # 10
print(proc.process("hello")) # HELLO
```

A function returning a decorator enables parameterized decorators, where the decorator's behavior can be customized via arguments.

```python
def repeat_result(times):
    """Return a decorator that repeats the result."""
    def decorator(func):
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            return result * times
        return wrapper
    return decorator

@repeat_result(times=3)
def get_number():
    return 5

print(get_number())  # 15 (5 repeated 3 times in result)
```

__slots__ restricts attributes on a class for memory efficiency. Properties work with __slots__ to provide controlled attribute access.

```python
class Point:
    __slots__ = ['_x', '_y']

    def __init__(self, x, y):
        self._x = x
        self._y = y

    @property
    def x(self):
        return self._x

    @x.setter
    def x(self, value):
        if value < 0:
            raise ValueError("x must be non-negative")
        self._x = value

p = Point(5, 10)
print(p.x)  # 5
p.x = 20
p.z = 30    # AttributeError: 'Point' object has no attribute 'z'
```

The descriptor protocol involves __get__(), __set__(), and __delete__() methods. Descriptors control attribute access at the class level.

```python
class Descriptor:
    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        return getattr(obj, f'_{self.name}', None)

    def __set__(self, obj, value):
        setattr(obj, f'_{self.name}', value)

class MyClass:
    x = Descriptor()

    def __init__(self, value):
        self.x = value

obj = MyClass(42)
print(obj.x)  # 42
```

A decorator factory is a function that creates and returns a decorator, enabling configuration of decorator behavior.

```python
def decorator_factory(config):
    def decorator(func):
        def wrapper(*args, **kwargs):
            print(f"Config: {config}")
            return func(*args, **kwargs)
        return wrapper
    return decorator

@decorator_factory(config={"enabled": True})
def my_func():
    print("Function called")

my_func()
# Config: {'enabled': True}
# Function called
```

A protocol defines a structural interface without inheritance. Objects matching the protocol's methods are compatible, enabling duck typing with type checking.

```python
from typing import Protocol

class Drawable(Protocol):
    def draw(self) -> None: ...

class Circle:
    def draw(self) -> None:
        print("Drawing circle")

def render(obj: Drawable) -> None:
    obj.draw()

render(Circle())  # Drawing circle
```

Memoization decorators cache recursive function results, dramatically improving performance for overlapping subproblems.

```python
from functools import lru_cache

@lru_cache(maxsize=None)
def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

print(fibonacci(30))  # 832040 (fast with caching)
print(fibonacci.cache_info())  # CacheInfo(hits=28, misses=31, ...)
```

Auto-currying automatically converts a multi-argument function into a chain of single-argument functions.

```python
def auto_curry(func):
    from functools import wraps
    @wraps(func)
    def curried(*args):
        if len(args) >= func.__code__.co_argcount:
            return func(*args)
        return lambda *more_args: curried(*(args + more_args))
    return curried

@auto_curry
def add(a, b, c):
    return a + b + c

print(add(1)(2)(3))      # 6
print(add(1, 2)(3))      # 6
print(add(1)(2, 3))      # 6
print(add(1, 2, 3))      # 6
```

singledispatch enables generic functions with type-based dispatch, improving code organization and extensibility.

```python
from functools import singledispatch

@singledispatch
def serialize(obj):
    raise NotImplementedError(f"Cannot serialize {type(obj)}")

@serialize.register(int)
def _(obj):
    return str(obj)

@serialize.register(list)
def _(obj):
    return f"[{', '.join(serialize(x) for x in obj)}]"

@serialize.register(dict)
def _(obj):
    return f"{{{', '.join(f'{k}:{serialize(v)}' for k,v in obj.items())}}}"

print(serialize(42))              # '42'
print(serialize([1, 2, 3]))       # '[1, 2, 3]'
print(serialize({"a": 1, "b": 2})) # '{a:1, b:2}'
```

A memoization wrapper can cache results based on function arguments, handling complex cache key scenarios.

```python
from functools import wraps

def memoize_with_args(func):
    cache = {}
    @wraps(func)
    def wrapper(*args, **kwargs):
        # Create cache key from args and kwargs
        key = (args, tuple(sorted(kwargs.items())))
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]
    wrapper.cache = cache
    return wrapper

@memoize_with_args
def expensive(a, b, multiplier=1):
    return (a + b) * multiplier

print(expensive(2, 3))            # 5
print(expensive(2, 3, multiplier=2))  # 10
print(expensive.cache)  # Cache contents
```

reduce() can create validation pipelines by chaining validators that transform and validate data.

```python
from functools import reduce

def validate_age(data):
    age = data.get("age")
    if not isinstance(age, int) or age < 0 or age > 150:
        raise ValueError(f"Invalid age: {age}")
    return data

def validate_name(data):
    name = data.get("name")
    if not isinstance(name, str) or len(name) == 0:
        raise ValueError(f"Invalid name: {name}")
