Functions can accept multiple callback functions and invoke them conditionally or sequentially.

```python
def process_with_callbacks(data, *callbacks):
    result = data
    for callback in callbacks:
        result = callback(result)
    return result

def double(x):
    return x * 2

def add_ten(x):
    return x + 10

def square(x):
    return x ** 2

result = process_with_callbacks(5, double, add_ten, square)
print(result)  # ((5*2)+10)^2 = 400
```

functools works with copy semantics. functools.wraps preserves function identity; deepcopy creates independent copies of objects.

```python
from copy import deepcopy
from functools import wraps

def make_functions():
    x = 0
    def f1():
        return x
    def f2():
        return x
    return f1, f2

f1, f2 = make_functions()
print(f1.__code__ is f2.__code__)  # True (same code object)

# functools.wraps preserves code object
def decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper
```

A decorator can fix the mutable default argument pitfall by creating new defaults on each call.

```python
from functools import wraps

def fix_mutable_defaults(func):
    defaults = func.__defaults__
    @wraps(func)
    def wrapper(*args, **kwargs):
        # Create new instances of mutable defaults
        new_defaults = [arg.copy() if isinstance(arg, (list, dict)) else arg for arg in (defaults or [])]
        func.__defaults__ = tuple(new_defaults)
        return func(*args, **kwargs)
    return wrapper

@fix_mutable_defaults
def append_to_list(item, lst=None):
    if lst is None:
        lst = []
    lst.append(item)
    return lst

print(append_to_list(1))   # [1]
print(append_to_list(2))   # [2], not [1, 2]
```
